from collections import deque


def classify_route(n, edges, s, t):
    edges = list(edges)
    forward = [[] for _ in range(n)]
    reverse = [[] for _ in range(n)]
    for u, v, w in edges:
        forward[u].append(v)
        reverse[v].append(u)

    def reachable(start, adjacency):
        seen = [False] * n
        seen[start] = True
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adjacency[u]:
                if not seen[v]:
                    seen[v] = True
                    queue.append(v)
        return seen

    from_s = reachable(s, forward)
    if not from_s[t]:
        return ("UNREACHABLE", None)

    to_t = reachable(t, reverse)
    relevant = [from_s[v] and to_t[v] for v in range(n)]
    k = sum(relevant)
    relevant_edges = [
        (u, v, w) for u, v, w in edges
        if relevant[u] and relevant[v]
    ]

    dist = [None] * n
    dist[s] = 0

    # Synchronous rounds: each round reads only the previous round.
    for _ in range(k - 1):
        next_dist = dist.copy()
        changed = False
        for u, v, w in relevant_edges:
            if dist[u] is None:
                continue
            candidate = dist[u] + w
            if next_dist[v] is None or candidate < next_dist[v]:
                next_dist[v] = candidate
                changed = True
        dist = next_dist
        if not changed:
            return ("FINITE", dist[t])

    # An improvement on round k certifies a relevant negative cycle.
    for u, v, w in relevant_edges:
        if dist[u] is not None:
            candidate = dist[u] + w
            if dist[v] is None or candidate < dist[v]:
                return ("UNBOUNDED", None)

    return ("FINITE", dist[t])
```

